    def pw(self, *args, stdin=None):
        env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "src"))
        return subprocess.run(
            [sys.executable, "-m", "pennywise"] + list(args),
            input=stdin,
            capture_output=True,
            env=env,
            cwd=self.dir,
        )

    def test_module_balance(self):
        r = self.pw("balance", self.path)
        self.assertEqual((r.returncode, r.stdout, r.stderr), (0, b"1557.50\n", b""))

    def test_module_stdin(self):
        r = self.pw("summary", "-", stdin=SAMPLE.encode())
        self.assertEqual(r.returncode, 0)
        self.assertEqual(r.stdout.decode().splitlines()[-1], "salary  2500.00")

    def test_module_exit_codes(self):
        self.assertEqual(self.pw().returncode, 2)
        bad = self.write("bad.txt", "oops\n")
