        self.assertEqual((r.returncode, r.stdout), (1, b""))
        self.assertIn(b"line 1", r.stderr)
        self.assertEqual(self.pw("balance", os.path.join(self.dir, "missing")).returncode, 2)


class ClosedStdoutTests(CliCase):
    """Output consumer stops reading early (``| head -1``) or stdout is closed."""

    def big(self, kind="line"):
        if kind == "groups":
            rows = ("2024-01-01 cat%d -1 n\n" % i for i in range(20000))
        else:
            rows = ("2024-01-01 food -1 n%d\n" % i for i in range(20000))
        return self.write("big.txt", "".join(rows))

    def piped(self, args, stdin_file=None):
        env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "src"))
        stdin = open(stdin_file, "rb") if stdin_file else None
        try:
            proc = subprocess.Popen(
                [sys.executable, "-m", "pennywise"] + list(args),
                stdin=stdin, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                env=env, cwd=self.dir,
            )
        finally:
            if stdin:
                stdin.close()
        first = proc.stdout.readline()
        proc.stdout.close()  # consumer is gone: the next write hits a closed pipe
        err = proc.stderr.read()
        proc.stderr.close()
        return first, proc.wait(timeout=60), err

    def assertQuiet(self, args, stdin_file=None):
        first, code, err = self.piped(args, stdin_file)
        self.assertTrue(first.endswith(b"\n"), first)
        self.assertEqual(err, b"")
        self.assertIn(code, (0, 141))

    def test_list_head(self):
        self.assertQuiet(["list", self.big()])

    def test_list_stdin_head(self):
        path = self.big()
        self.assertQuiet(["list", "-"], stdin_file=path)

    def test_export_head(self):
        self.assertQuiet(["export", self.big()])

    def test_summary_many_groups_head(self):
        self.assertQuiet(["summary", self.big("groups")])

    def test_list_json_head(self):
        self.assertQuiet(["list", self.big(), "--json"])

    def test_closed_stdout(self):
        env = dict(os.environ, PYTHONPATH=os.path.join(ROOT, "src"))
        for args in (["balance", self.path], ["list", self.path]):
            r = subprocess.run(
                "exec %s -m pennywise %s >&-"
                % (sys.executable, " ".join(args)),
                shell=True, capture_output=True, env=env, cwd=self.dir,
            )
            self.assertEqual(r.stderr, b"", args)
            self.assertIn(r.returncode, (0, 141), args)


